package com.bank.generics;

import java.lang.reflect.InvocationTargetException;
import java.util.logging.Logger;

// Because T is ERASED at runtime, `new T()` is impossible. Workaround: a Class<T> token.
public class GenericRepository<T> {
    private static final Logger log = Logger.getLogger(GenericRepository.class.getName());
    private final Class<T> type;

    public GenericRepository(Class<T> type) { this.type = type; }

    // T newEntity() { return new T(); }  // ← DOES NOT COMPILE (type erased)
    public T newEntity() {
        try {
            // reflection recovers what erasure removed, using the Class token
            T instance = type.getDeclaredConstructor().newInstance();
            log.info(() -> "Created new " + type.getSimpleName() + " via Class token");
            return instance;
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException("cannot instantiate " + type, e);
        }
    }
}
