package com.bank.generics;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class BalanceUtil {
    private static final Logger log = Logger.getLogger(BalanceUtil.class.getName());

    // PRODUCER → ? extends Account: we READ accounts out, so the list may hold
    // Account or ANY subtype (SavingsAccount). We can read as Account; we CANNOT add.
    public static BigDecimal totalBalance(List<? extends Account> accounts) {
        BigDecimal sum = BigDecimal.ZERO;
        for (Account a : accounts) {            // safe: every element is at least Account
            sum = sum.add(a.getBalance());
        }
        // accounts.add(new Account());  // ← DOES NOT COMPILE (unknown exact subtype)
        log.info(() -> "Total balance of " + accounts.size() + " accounts = Rs." + sum);
        return sum;
    }

    // CONSUMER → ? super SavingsAccount: we WRITE savings into it, so the list may be
    // typed to SavingsAccount or ANY supertype (Account, Object). We can add; reads give Object.
    public static void addSavings(List<? super SavingsAccount> sink, String id, BigDecimal bal) {
        sink.add(new SavingsAccount(id, bal));  // safe: a SavingsAccount fits any supertype
        log.info(() -> "Added SavingsAccount " + id + " into a ? super sink");
    }

    // Generic-only overload DOES NOT COMPILE — both erase to the same signature:
    //   void process(List<String> x) {}
    //   void process(List<Integer> x) {}   // ← name clash after erasure
}
