package com.bank.generics;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class ErasureDemo {
    private static final Logger log = Logger.getLogger(ErasureDemo.class.getName());

    public static void main(String[] args) {
        // 1) new T() workaround via Class token
        GenericRepository<Account> repo = new GenericRepository<>(Account.class);
        Account fresh = repo.newEntity();
        fresh.setAccountId("SAV2001");

        // 2) PECS producer: list of subtype read as Account
        List<SavingsAccount> savings = new ArrayList<>();
        savings.add(new SavingsAccount("SAV2001", new BigDecimal("1000000")));  // Rajesh
        savings.add(new SavingsAccount("CUR3001", new BigDecimal("250000")));   // Priya
        BalanceUtil.totalBalance(savings);      // accepts List<? extends Account>

        // 3) PECS consumer: write SavingsAccount into a list typed to a supertype
        List<Account> accounts = new ArrayList<>();
        BalanceUtil.addSavings(accounts, "SAV9999", new BigDecimal("500000"));

        // 4) erasure facts
        List<String> strings = new ArrayList<>();
        List<Integer> ints = new ArrayList<>();
        log.info("List<String> and List<Integer> are the same runtime class: "
            + (strings.getClass() == ints.getClass()));    // true → erased to List
        log.info("instanceof List<String> is illegal; only (strings instanceof List<?>) = "
            + (strings instanceof List<?>));
        // Object[] arr = new SavingsAccount[2];  // arrays are reified (allowed),
        // but `new T[2]` inside a generic is NOT — arrays + erasure conflict.
    }
}
